using System;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed class SmartPreview:Control{
 public Image Wallpaper;public SmartColors Colors;readonly WallpaperLayerCache layers=new WallpaperLayerCache();
 public SmartPreview(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(StudioUi.Rail);if(Wallpaper!=null){double scale=Math.Max(Width/(double)Wallpaper.Width,Height/(double)Wallpaper.Height);float w=(float)(Wallpaper.Width*scale),h=(float)(Wallpaper.Height*scale);g.DrawImage(Wallpaper,(Width-w)/2,(Height-h)/2,w,h);}if(Colors==null)return;var p=Colors;layers.Draw(g,Wallpaper,p.Effects,new RectangleF(0,0,150,Height),new SizeF(Width,Height),0);BackgroundEffects.DrawMaterial(g,new RectangleF(0,0,150,Height),BackgroundEffects.RegionColor(p.Effects,0),p.Effects.Friends,0);Box(g,p.Theme.Colors[10+p.RuntimeMode],8,45,134,44);Word(g,"选中的会话",SmartPalette.SelectionInk(p.Theme,p.RuntimeMode,p.Text),18,57,9);Word(g,"●  导航与图标",p.Accent,16,12,9);Word(g,"普通会话",p.Text,18,106,9);Word(g,"多色组合预览",p.Icons,18,129,8);Box(g,p.Theme.Colors[14+p.RuntimeMode],166,18,215,49);Word(g,"这是一条接收消息",p.Text,177,27,9);Word(g,"副色形成接收层次",p.Text,177,46,8);Box(g,p.Theme.Colors[12+p.RuntimeMode],Width-248,88,230,49);Word(g,"这是自己发送的消息",p.Text,Width-237,96,9);Word(g,"主色保留图片特征",p.Text,Width-237,115,8);using(var b=new SolidBrush(Color.FromArgb((int)Math.Round((1-(1-0d)*(1-p.Effects.Input/100d))*255),ColorTranslator.FromHtml(BackgroundEffects.RegionColor(p.Effects,2)))))g.FillRectangle(b,158,Height-42,Width-166,34);using(var pen=new Pen(ColorTranslator.FromHtml(p.Border),1))g.DrawRectangle(pen,163,Height-38,Width-177,26);Word(g,"输入消息…",p.Text,175,Height-33,9);}
 void Box(Graphics g,string color,int x,int y,int w,int h){using(var path=new GraphicsPath()){const int d=12;path.AddArc(x,y,d,d,180,90);path.AddArc(x+w-d,y,d,d,270,90);path.AddArc(x+w-d,y+h-d,d,d,0,90);path.AddArc(x,y+h-d,d,d,90,90);path.CloseFigure();using(var b=new SolidBrush(ColorTranslator.FromHtml(color)))g.FillPath(b,path);}}
 protected override void Dispose(bool disposing){if(disposing)layers.Dispose();base.Dispose(disposing);}
 void Word(Graphics g,string text,string color,int x,int y,int size=10){using(var f=new Font("Microsoft YaHei UI",size))using(var b=new SolidBrush(ColorTranslator.FromHtml(color)))g.DrawString(text,f,b,x,y);}
}
internal sealed class PaletteMapCanvas:Control{
 internal Bitmap Picture;internal ImageSwatch[] Swatches=new ImageSwatch[0];internal event Action<Color> ColorPicked;
 internal PaletteMapCanvas(){DoubleBuffered=true;Cursor=Cursors.Cross;AccessibleName="整图色彩地图，点击图片取色";}
 Rectangle ImageRect(){if(Picture==null)return Rectangle.Empty;double scale=Math.Min(Width/(double)Picture.Width,Height/(double)Picture.Height);int w=(int)(Picture.Width*scale),h=(int)(Picture.Height*scale);return new Rectangle((Width-w)/2,(Height-h)/2,w,h);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(StudioUi.Rail);if(Picture==null)return;var r=ImageRect();e.Graphics.DrawImage(Picture,r);for(int i=0;i<Swatches.Length;i++){float x=r.X+Swatches[i].X*r.Width,y=r.Y+Swatches[i].Y*r.Height;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var b=new SolidBrush(Color.FromArgb(210,25,35,40)))e.Graphics.FillEllipse(b,x-10,y-10,20,20);using(var p=new Pen(Color.White,1.5f))e.Graphics.DrawEllipse(p,x-10,y-10,20,20);using(var f=new Font("Microsoft YaHei UI",7.5f,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,(i+1).ToString(),f,new Rectangle((int)x-10,(int)y-9,20,18),Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);var r=ImageRect();if(Picture==null||!r.Contains(e.Location))return;int x=Math.Min(Picture.Width-1,(e.X-r.X)*Picture.Width/r.Width),y=Math.Min(Picture.Height-1,(e.Y-r.Y)*Picture.Height/r.Height);if(ColorPicked!=null)ColorPicked(Picture.GetPixel(x,y));}
 protected override void Dispose(bool d){if(d&&Picture!=null)Picture.Dispose();base.Dispose(d);}
}
internal sealed class SmartPaletteDialog:Form{
 readonly string source;readonly ComboBox variant=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList},appearance=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};readonly SmartPreview preview=new SmartPreview();readonly PaletteMapCanvas map=new PaletteMapCanvas();readonly Panel swatches=new Panel();readonly Label status=new Label(),explanation=new Label();readonly Button use=new Button();readonly CheckBox runtime=new CheckBox();readonly Button[] roleButtons=new Button[4];readonly ToolTip roleTips=new ToolTip();ImageSwatch[] palette;PaletteAssignment assignment;int generation,selectedRole;bool rendering;string initialSeed;public SmartColors Value;
 static readonly string[] RoleTitles={"自己气泡 / 发送与选中","对方气泡 / 接收消息","界面基底 / 面板层次","强调点缀 / 图标"};
 public SmartPaletteDialog(string path){source=path;Text="整图配色工作台";Font=new Font("Microsoft YaHei UI",9.5f);ClientSize=new Size(1180,760);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=StudioUi.Paper;
  Controls.Add(StudioUi.Label("整图配色工作台",new Rectangle(24,19,800,34),20,true));Controls.Add(StudioUi.Label("提取整张图的多种颜色，再按用途组合主题。图片取色只在本机进行。",new Rectangle(26,61,1000,25),9));
  Controls.Add(StudioUi.Label("原图与取色位置",new Rectangle(24,103,500,24),11,true));map.SetBounds(24,136,540,260);using(var im=Image.FromFile(path)){map.Picture=new Bitmap(im);preview.Wallpaper=new Bitmap(im);}map.ColorPicked+=async color=>{SetRole(SmartPalette.Hex(color));await Generate();};Controls.Add(map);Controls.Add(StudioUi.Label("点击原图可直接取色；编号对应右侧整图代表色。",new Rectangle(24,406,540,23),9));Controls.Add(StudioUi.Label("组合后的主题预览",new Rectangle(24,439,540,25),11,true));preview.SetBounds(24,471,540,198);Controls.Add(preview);
  Controls.Add(StudioUi.Label("01  整图代表色",new Rectangle(594,103,540,25),11,true));swatches.SetBounds(594,136,562,176);Controls.Add(swatches);Controls.Add(StudioUi.Label("按面积、色彩差异与鲜艳度保留多类颜色；占比是采样估计。",new Rectangle(594,318,562,22),8.5f));Controls.Add(StudioUi.Label("02  分配到不同用途",new Rectangle(594,354,562,25),11,true));
  for(int i=0;i<4;i++){int index=i;var b=StudioUi.Button(RoleTitles[i],new Rectangle(594,391+i*44,430,36));b.TextAlign=ContentAlignment.MiddleLeft;b.Padding=new Padding(12,0,0,0);b.Click+=delegate{selectedRole=index;RefreshRoles();status.Text="已选择"+RoleTitles[index]+"，再点上方色块或原图。";};roleButtons[i]=b;Controls.Add(b);var edit=StudioUi.Button("编辑…",new Rectangle(1036,391+i*44,120,36));edit.Click+=async delegate{if(assignment==null)return;selectedRole=index;StudioColorPicker.ImageColors=palette.Select(c=>c.Hex).ToArray();using(var d=new StudioColorPicker{Color=ColorTranslator.FromHtml(GetRole(index))})if(d.ShowDialog(this)==DialogResult.OK){SetRole(SmartPalette.Hex(d.Color));await Generate();}};Controls.Add(edit);}
  variant.Items.AddRange(new object[]{"协调（推荐）","鲜明","柔和"});variant.SetBounds(594,581,315,30);variant.SelectedIndex=0;variant.AccessibleName="配色风格";Controls.Add(variant);appearance.Items.AddRange(new object[]{"浅色外观","深色外观"});appearance.SetBounds(925,581,231,30);appearance.SelectedIndex=AppearanceProfiles.Mode;Controls.Add(appearance);variant.SelectedIndexChanged+=async delegate{await Generate();};appearance.SelectedIndexChanged+=async delegate{await Generate();};var reset=StudioUi.Button("重新自动分配",new Rectangle(594,625,160,34));reset.Click+=async delegate{if(palette==null)return;assignment=SmartPalette.AssignPalette(palette);await Generate();};Controls.Add(reset);explanation.SetBounds(770,620,386,52);explanation.ForeColor=StudioUi.Muted;Controls.Add(explanation);
  var footer=new Panel{Dock=DockStyle.Bottom,Height=72,BackColor=Color.FromArgb(252,253,253)};runtime.Text="同时载入文字、图标和局部可读性设置";runtime.Checked=true;runtime.SetBounds(24,9,700,25);footer.Controls.Add(runtime);status.SetBounds(25,39,880,25);status.ForeColor=StudioUi.Muted;footer.Controls.Add(status);use.SetBounds(964,18,192,38);use.Text="载入这套组合";use.FlatStyle=FlatStyle.Flat;use.BackColor=StudioUi.Accent;use.ForeColor=Color.White;use.Enabled=false;use.Click+=delegate{if(Value==null)return;Value.IncludeRuntime=runtime.Checked;DialogResult=DialogResult.OK;};footer.Controls.Add(use);Controls.Add(footer);Shown+=async delegate{if(!rendering)await Generate();};FormClosed+=delegate{roleTips.Dispose();generation++;if(preview.Wallpaper!=null)preview.Wallpaper.Dispose();};}
 string GetRole(int i){return i==0?assignment.Primary:i==1?assignment.Secondary:i==2?assignment.Neutral:assignment.Accent;}
 void SetRole(string color){if(assignment==null)return;if(selectedRole==0)assignment.Primary=color;else if(selectedRole==1)assignment.Secondary=color;else if(selectedRole==2)assignment.Neutral=color;else assignment.Accent=color;}
 void RefreshRoles(){if(assignment==null)return;for(int i=0;i<4;i++){string applied=Value==null?GetRole(i):i==0?Value.Theme.Colors[12+Value.RuntimeMode]:i==1?Value.Theme.Colors[14+Value.RuntimeMode]:i==2?Value.Theme.Colors[Value.RuntimeMode]:Value.Accent;roleButtons[i].Text=RoleTitles[i]+"   "+applied;roleTips.SetToolTip(roleButtons[i],"图片来源色 "+GetRole(i)+"；最终界面色 "+applied);roleButtons[i].Font=new Font(Font.FontFamily,8.5f);roleButtons[i].BackColor=i==selectedRole?Color.FromArgb(223,239,233):Color.FromArgb(252,253,253);roleButtons[i].FlatAppearance.BorderColor=i==selectedRole?StudioUi.Accent:StudioUi.Line;}}
 async Task Generate(){int request=++generation,index=variant.SelectedIndex==0?3:variant.SelectedIndex,mode=appearance.SelectedIndex;use.Enabled=false;status.Text="正在分析整图颜色与区域分布…";try{if(palette==null){var extracted=await Task.Run(()=>SmartPalette.ExtractImagePalette(source));if(IsDisposed||request!=generation)return;palette=extracted;assignment=SmartPalette.AssignPalette(palette);if(initialSeed!=null)assignment.Primary=initialSeed;}var seeds=assignment.Copy();var result=await Task.Run(()=>SmartPalette.GenerateMapped(source,index,mode,seeds,palette));if(IsDisposed||request!=generation)return;Value=result;using(var original=Image.FromFile(source)){var old=preview.Wallpaper;preview.Wallpaper=BackgroundEffects.Transform(original,result.Effects);if(old!=null)old.Dispose();}preview.Colors=result;preview.Invalidate();map.Swatches=palette;map.Invalidate();StudioColorPicker.ImageColors=palette.Select(c=>c.Hex).ToArray();foreach(Control old in swatches.Controls.Cast<Control>().ToArray())old.Dispose();swatches.Controls.Clear();for(int i=0;i<palette.Length;i++){ImageSwatch c=palette[i];var chip=new ColorTile{Swatch=ColorTranslator.FromHtml(c.Hex),Caption=(i+1)+"  "+c.Name,Detail=c.Hex.Substring(1)+" "+(c.Share<.01?"<1%":(c.Share*100).ToString("0")+"%"),Bounds=new Rectangle(i%6*94,i/6*87,88,80),Font=new Font(Font.FontFamily,8.5f),Selected=GetRole(selectedRole)==c.Hex,AccessibleName=c.Name+" "+c.Hex};chip.Click+=async delegate{SetRole(c.Hex);await Generate();};swatches.Controls.Add(chip);}RefreshRoles();explanation.Text="行内显示实际界面色；悬停查看图片来源色。";double ratio=Math.Min(SmartPalette.Contrast(ColorTranslator.FromHtml(result.Text),ColorTranslator.FromHtml(result.Theme.Colors[12+mode])),SmartPalette.Contrast(ColorTranslator.FromHtml(result.Text),ColorTranslator.FromHtml(result.Theme.Colors[14+mode])));status.Text=palette.Length+" 种整图代表色 · 正文最低对比度 "+ratio.ToString("0.0")+":1 · 尚未修改微信";use.Enabled=true;}catch(Exception e){if(!IsDisposed&&request==generation)status.Text="无法生成："+e.Message;}}
 public async Task RenderForTest(string path){await RenderForTest(path,1,1,null);}public async Task RenderForTest(string path,int mode){await RenderForTest(path,mode,1,null);}public async Task RenderForTest(string path,int mode,int style,string seed){rendering=true;initialSeed=seed;variant.SelectedIndex=style==1||style==2?style:0;appearance.SelectedIndex=mode;StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);ShowInTaskbar=false;Show();await Generate();Application.DoEvents();if(Value==null||!use.Enabled)throw new InvalidOperationException("Palette workbench render did not finish generation");using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(path);}Close();}
